GLOBAL_CSS = '<style>@import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\');\n:root {\n  --ff-primary: #12312E;\n  --ff-primary-hover: #1B4A44;\n  --ff-accent: #1F7A63;\n  --ff-accent-dark: #155C4B;\n  --ff-accent-soft: #E8F3EE;\n  --ff-bg: #F6F8F7;\n  --ff-surface: #FFFFFF;\n  --ff-text: #16211F;\n  --ff-muted: #4C5B57;\n  --ff-border: #DCE5E1;\n  --ff-success: #1E7A55;\n  --ff-success-bg: #E6F4EC;\n  --ff-warning: #8A5A12;\n  --ff-warning-bg: #FFF4DC;\n  --ff-danger: #A33A3A;\n  --ff-danger-bg: #FBEAEA;\n  --ff-info: #2C5F87;\n  --ff-info-bg: #EAF2F8;\n  --ff-focus: #0F6B57;\n  --ff-radius: 12px;\n  --ff-shadow: 0 1px 2px rgba(16, 33, 31, 0.04), 0 8px 24px rgba(16, 33, 31, 0.05);\n  --ff-font: \'Inter\', \'Segoe UI\', system-ui, -apple-system, sans-serif;\n}\n\nhtml, body, [class*="css"] { font-family: var(--ff-font); }\n\n.stApp {\n  background: var(--ff-bg);\n  color: var(--ff-text);\n}\n\n/* Una sola jerarquía tipográfica: H1 de página, H2 de sección, cuerpo. */\nh1 {\n  font-size: 2.15rem !important;\n  line-height: 1.15 !important;\n  font-weight: 800 !important;\n  letter-spacing: -0.025em;\n  color: var(--ff-primary);\n  margin: 0 0 8px !important;\n}\nh2 {\n  font-size: 1.35rem !important;\n  line-height: 1.25 !important;\n  font-weight: 750 !important;\n  letter-spacing: -0.015em;\n  color: var(--ff-primary);\n}\nh3 {\n  font-size: 1.05rem !important;\n  line-height: 1.35 !important;\n  font-weight: 700 !important;\n  color: var(--ff-text);\n}\np, li, .stMarkdown { line-height: 1.6; }\n[data-testid="stCaptionContainer"] {\n  color: var(--ff-muted);\n  font-size: 0.82rem;\n  line-height: 1.5;\n}\n\n/* Contenedor principal y reflujo sin scroll horizontal. */\n.block-container {\n  max-width: 1320px;\n  padding-top: 1.4rem;\n  padding-bottom: 3rem;\n  padding-left: 2rem;\n  padding-right: 2rem;\n}\n\n/* ---- Sidebar ---- */\n[data-testid="stSidebar"] {\n  background: var(--ff-surface);\n  border-right: 1px solid var(--ff-border);\n}\n[data-testid="stSidebar"] .block-container {\n  padding: 0.9rem 0.85rem 1.25rem;\n}\n[data-testid="stSidebar"] [data-testid="stFullScreenFrame"] > div {\n  width: 100% !important;\n}\n[data-testid="stSidebar"] [data-testid="stImage"],\n[data-testid="stSidebar"] [data-testid="stImageContainer"] {\n  display: flex;\n  justify-content: center;\n  width: 100% !important;\n  margin: 2px 0 6px;\n}\n[data-testid="stSidebar"] [data-testid="stImage"] img {\n  border-radius: 0;\n  box-shadow: none;\n  background: transparent;\n  margin: 0 auto;\n}\n[data-testid="stSidebar"] .stButton button {\n  justify-content: flex-start;\n  text-align: left;\n  min-height: 32px;\n  padding: 4px 10px;\n  font-size: 0.88rem;\n  font-weight: 600;\n  border-color: transparent;\n  background: transparent;\n  color: var(--ff-text);\n  white-space: nowrap;\n}\n[data-testid="stSidebar"] .stButton button:hover {\n  background: var(--ff-accent-soft);\n  border-color: transparent;\n  color: var(--ff-primary);\n}\n[data-testid="stSidebar"] .stButton button[kind="primary"] {\n  background: var(--ff-accent-soft);\n  border-color: transparent;\n  box-shadow: inset 3px 0 0 var(--ff-primary);\n  color: var(--ff-primary);\n  font-weight: 700;\n}\n[data-testid="stSidebar"] .stButton button:disabled {\n  background: var(--ff-bg);\n  border-color: var(--ff-border);\n  color: var(--ff-muted) !important;\n  opacity: 1 !important;\n}\n[data-testid="stSidebar"] .stButton button:disabled p {\n  color: var(--ff-muted) !important;\n}\n[data-testid="stSidebar"] hr { margin: 6px 0; }\n[data-testid="stSidebarHeader"] { margin-bottom: 0 !important; }\n[data-testid="stSidebarUserContent"] { padding-bottom: 0 !important; }\n[data-testid="stSidebarUserContent"] > div > [data-testid="stVerticalBlock"] {\n  gap: 4px !important;\n}\n\n/* ---- Cabeceras de página ---- */\n.ff-eyebrow {\n  font-size: 0.72rem;\n  font-weight: 800;\n  letter-spacing: 0.13em;\n  text-transform: uppercase;\n  color: var(--ff-accent-dark);\n  margin-bottom: 2px;\n}\n.ff-page-subtitle {\n  color: var(--ff-muted);\n  font-size: 0.95rem;\n  line-height: 1.6;\n  max-width: 760px;\n  margin: 0 0 4px;\n}\n.ff-section-title {\n  font-size: 1.22rem;\n  font-weight: 750;\n  letter-spacing: -0.01em;\n  color: var(--ff-primary);\n  margin: 26px 0 2px;\n}\n.ff-section-subtitle {\n  color: var(--ff-muted);\n  font-size: 0.86rem;\n  line-height: 1.5;\n  margin: 0 0 8px;\n}\n.ff-muted { color: var(--ff-muted); }\n\n/* ---- Tarjetas nativas y heredadas ---- */\n[data-testid="stVerticalBlockBorderWrapper"] {\n  border-radius: var(--ff-radius);\n  border-color: var(--ff-border);\n  background: var(--ff-surface);\n}\n.ff-card {\n  background: var(--ff-surface);\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  padding: 20px 22px;\n  box-shadow: none;\n  min-height: auto;\n}\n.ff-card-label {\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--ff-muted);\n}\n.ff-card-value {\n  font-size: 1.55rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  color: var(--ff-primary);\n  margin: 5px 0 3px;\n}\n.ff-card-foot {\n  font-size: 0.8rem;\n  color: var(--ff-muted);\n  line-height: 1.45;\n}\n\n/* ---- Estados ---- */\n.ff-badge {\n  display: inline-block;\n  padding: 4px 10px;\n  border-radius: 999px;\n  font-size: 0.73rem;\n  font-weight: 750;\n  letter-spacing: 0.02em;\n  line-height: 1.4;\n}\n.ff-badge-ok { background: var(--ff-success-bg); color: var(--ff-success); }\n.ff-badge-warn { background: var(--ff-warning-bg); color: var(--ff-warning); }\n.ff-badge-danger { background: var(--ff-danger-bg); color: var(--ff-danger); }\n.ff-badge-info { background: var(--ff-info-bg); color: var(--ff-info); }\n.ff-badge-muted { background: #EEF2F0; color: var(--ff-muted); }\n\n.ff-note {\n  border-left: 4px solid var(--ff-accent);\n  background: var(--ff-accent-soft);\n  border-radius: 0 var(--ff-radius) var(--ff-radius) 0;\n  padding: 12px 15px;\n  font-size: 0.88rem;\n  color: var(--ff-primary);\n  line-height: 1.55;\n}\n.ff-empty {\n  text-align: center;\n  padding: 8px 6px 2px;\n}\n.ff-empty p { margin-bottom: 4px; }\n\n/* ---- Pasos del flujo ---- */\n.ff-step {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  background: var(--ff-surface);\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  padding: 11px 12px;\n  min-height: 76px;\n  height: 100%;\n}\n.ff-step-icon {\n  width: 34px;\n  height: 34px;\n  border-radius: 10px;\n  background: var(--ff-accent-soft);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.95rem;\n  flex-shrink: 0;\n}\n.ff-step strong {\n  display: block;\n  font-size: 0.82rem;\n  line-height: 1.3;\n  color: var(--ff-text);\n}\n.ff-step span {\n  display: block;\n  font-size: 0.73rem;\n  line-height: 1.35;\n  color: var(--ff-muted);\n  margin-top: 2px;\n}\n\n/* ---- Botones ---- */\n.stButton > button,\n.stDownloadButton > button,\n.stFormSubmitButton > button {\n  border-radius: var(--ff-radius);\n  font-weight: 650;\n  min-height: 42px;\n  padding: 8px 16px;\n  transition: background-color .15s ease, border-color .15s ease;\n}\n.stButton > button[kind="primary"],\n.stFormSubmitButton > button[kind="primary"],\n.stDownloadButton > button[kind="primary"] {\n  background: var(--ff-accent);\n  border-color: var(--ff-accent);\n  color: #FFFFFF;\n}\n.stButton > button[kind="primary"]:hover,\n.stFormSubmitButton > button[kind="primary"]:hover {\n  background: var(--ff-accent-dark);\n  border-color: var(--ff-accent-dark);\n}\n.stButton > button:disabled,\n.stFormSubmitButton > button:disabled,\n.stDownloadButton > button:disabled {\n  background: #EDF1EF;\n  border-color: #D6DFDB;\n  color: #5A6864;\n  opacity: 1;\n}\n.stButton > button:focus-visible,\n.stDownloadButton > button:focus-visible,\n.stFormSubmitButton > button:focus-visible,\na:focus-visible,\n[role="radio"]:focus-visible,\n[role="checkbox"]:focus-visible {\n  outline: 3px solid var(--ff-focus);\n  outline-offset: 2px;\n}\n\n/* ---- Formularios ---- */\n.stTextInput input,\n.stTextArea textarea,\n.stNumberInput input,\n.stSelectbox [data-baseweb="select"] > div {\n  border-radius: var(--ff-radius) !important;\n  border-color: var(--ff-border) !important;\n  background: var(--ff-surface) !important;\n}\n.stTextInput label,\n.stTextArea label,\n.stNumberInput label,\n.stSelectbox label,\n.stSlider label,\n.stMultiSelect label {\n  color: var(--ff-text) !important;\n  font-weight: 600 !important;\n  font-size: 0.88rem !important;\n}\n[data-testid="stExpander"] {\n  background: var(--ff-surface);\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  overflow: hidden;\n}\n[data-testid="stExpander"] summary {\n  font-weight: 650;\n  color: var(--ff-text);\n}\n[data-testid="stForm"] {\n  background: transparent;\n  border: 0;\n  padding: 0;\n}\n.ff-form-action-spacer { height: 28px; }\n\n/* ---- Tablas y métricas ---- */\n[data-testid="stDataFrame"],\n[data-testid="stTable"] {\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  overflow: hidden;\n}\ndiv[data-testid="stMetric"] {\n  background: var(--ff-surface);\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  padding: 14px 16px;\n}\ndiv[data-testid="stMetricLabel"] {\n  color: var(--ff-muted);\n  font-size: 0.82rem;\n}\ndiv[data-testid="stMetricValue"] {\n  color: var(--ff-primary);\n  font-weight: 800;\n  letter-spacing: -0.02em;\n}\ndiv[data-testid="stMetricDelta"] {\n  font-size: 0.76rem;\n}\n\n/* ---- Tabs ---- */\n[data-testid="stTabs"] [role="tablist"] {\n  gap: 4px;\n  border-bottom: 1px solid var(--ff-border);\n}\n[data-testid="stTabs"] button[role="tab"] {\n  font-weight: 650;\n  color: var(--ff-muted);\n  padding: 8px 12px;\n}\n[data-testid="stTabs"] button[role="tab"][aria-selected="true"] {\n  color: var(--ff-primary);\n}\n\n/* ---- Barra de estado del estudio ---- */\n.ff-study-status {\n  background: var(--ff-bg);\n  border: 1px solid var(--ff-border);\n  border-radius: var(--ff-radius);\n  padding: 10px 12px;\n}\n.ff-study-status-title {\n  font-size: 0.72rem;\n  font-weight: 800;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--ff-muted);\n  margin-bottom: 4px;\n}\n.ff-study-status-value {\n  font-size: 0.86rem;\n  font-weight: 650;\n  color: var(--ff-primary);\n  line-height: 1.35;\n  margin-bottom: 6px;\n  overflow-wrap: anywhere;\n}\n.ff-nav-heading {\n  font-size: 0.7rem;\n  font-weight: 800;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  color: var(--ff-muted);\n  margin: 8px 0 4px 4px;\n}\n.ff-sidebar-promise {\n  color: var(--ff-muted);\n  font-size: 0.74rem;\n  line-height: 1.45;\n  padding: 2px 4px 0;\n}\n.ff-hero-actions [data-testid="stHorizontalBlock"] { gap: 8px; }\n\n/* ---- Aviso de riesgo / supuestos ---- */\n.ff-risk {\n  border-left: 4px solid var(--ff-warning);\n  background: var(--ff-warning-bg);\n  border-radius: 0 var(--ff-radius) var(--ff-radius) 0;\n  padding: 12px 15px;\n  color: #5D3C04;\n  font-size: 0.9rem;\n  line-height: 1.55;\n}\n.ff-ok {\n  border-left: 4px solid var(--ff-success);\n  background: var(--ff-success-bg);\n  border-radius: 0 var(--ff-radius) var(--ff-radius) 0;\n  padding: 12px 15px;\n  color: #0F4A33;\n  font-size: 0.9rem;\n  line-height: 1.55;\n}\n\n/* ---- Pie discreto (solo sidebar) ---- */\n.ff-footer {\n  font-size: 0.74rem;\n  color: var(--ff-muted);\n  padding-top: 8px;\n  line-height: 1.45;\n}\n\n/* ---- Accesibilidad y reflujo ---- */\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: .01ms !important;\n    transition-duration: .01ms !important;\n  }\n}\n@media (max-width: 900px) {\n  .block-container { padding-left: 1rem; padding-right: 1rem; }\n  h1 { font-size: 1.75rem !important; }\n  [data-testid="stHorizontalBlock"] { flex-wrap: wrap; }\n  [data-testid="column"] { min-width: 100% !important; }\n}\n</style>'


def inject() -> None:
    """Inyecta el CSS global en cada render."""
    st.markdown(GLOBAL_CSS, unsafe_allow_html=True)
